CREATE TABLE asset_types (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL);
CREATE TABLE locations (id UUID PRIMARY KEY, code VARCHAR(60) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, kind VARCHAR(40) NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION);
CREATE TABLE assets (id UUID PRIMARY KEY, fleet_number VARCHAR(80) UNIQUE NOT NULL, asset_type_id UUID NOT NULL REFERENCES asset_types(id), operational_status VARCHAR(40) NOT NULL, availability_status VARCHAR(40) NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, heading DOUBLE PRECISION, speed_kph DOUBLE PRECISION, energy_percent NUMERIC(5,2), odometer_km NUMERIC(14,2), engine_hours NUMERIC(14,2), current_location_id UUID REFERENCES locations(id), current_job_id UUID, last_telemetry_at TIMESTAMPTZ, driver_id VARCHAR(80), device_id VARCHAR(100) UNIQUE, trackit_id VARCHAR(100) UNIQUE, maintenance_status VARCHAR(40) NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_assets_status ON assets(operational_status, availability_status); CREATE INDEX idx_assets_position ON assets(latitude,longitude); CREATE INDEX idx_assets_last_telemetry ON assets(last_telemetry_at);
CREATE TABLE asset_capabilities (asset_id UUID REFERENCES assets(id) ON DELETE CASCADE, capability VARCHAR(80) NOT NULL, PRIMARY KEY(asset_id,capability));
CREATE TABLE asset_positions (id BIGSERIAL PRIMARY KEY, asset_id UUID NOT NULL REFERENCES assets(id), recorded_at TIMESTAMPTZ NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, heading DOUBLE PRECISION, speed_kph DOUBLE PRECISION); CREATE INDEX idx_positions_asset_time ON asset_positions(asset_id,recorded_at DESC);
CREATE TABLE asset_telemetry (id BIGSERIAL PRIMARY KEY, asset_id UUID NOT NULL REFERENCES assets(id), recorded_at TIMESTAMPTZ NOT NULL, fuel_percent NUMERIC(5,2), battery_percent NUMERIC(5,2), odometer_km NUMERIC(14,2), engine_hours NUMERIC(14,2), attributes JSONB NOT NULL DEFAULT '{}');
CREATE TABLE operational_zones (id UUID PRIMARY KEY, code VARCHAR(60) UNIQUE NOT NULL, zone_type VARCHAR(40) NOT NULL, boundary JSONB NOT NULL, restricted BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE map_nodes (id UUID PRIMARY KEY, code VARCHAR(60) UNIQUE NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, node_type VARCHAR(40) NOT NULL, zone_id UUID REFERENCES operational_zones(id));
CREATE TABLE road_segments (id UUID PRIMARY KEY, code VARCHAR(60) UNIQUE NOT NULL, from_node_id UUID NOT NULL REFERENCES map_nodes(id), to_node_id UUID NOT NULL REFERENCES map_nodes(id), distance_m DOUBLE PRECISION NOT NULL, speed_limit_kph DOUBLE PRECISION NOT NULL, congestion_factor DOUBLE PRECISION NOT NULL DEFAULT 1, priority_factor DOUBLE PRECISION NOT NULL DEFAULT 1, blocked BOOLEAN NOT NULL DEFAULT FALSE, restricted BOOLEAN NOT NULL DEFAULT FALSE, restrictions JSONB NOT NULL DEFAULT '{}'); CREATE INDEX idx_roads_nodes ON road_segments(from_node_id,to_node_id);
CREATE TABLE parking_zones (id UUID PRIMARY KEY, location_id UUID NOT NULL REFERENCES locations(id), capacity INTEGER NOT NULL CHECK(capacity>=0));
CREATE TABLE parking_spaces (id UUID PRIMARY KEY, parking_zone_id UUID NOT NULL REFERENCES parking_zones(id), code VARCHAR(60) UNIQUE NOT NULL, status VARCHAR(30) NOT NULL, supported_asset_types JSONB NOT NULL DEFAULT '[]', max_length_m DOUBLE PRECISION, reserved BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE service_stations (id UUID PRIMARY KEY, location_id UUID NOT NULL REFERENCES locations(id), station_type VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, service_type VARCHAR(30), operating_hours JSONB NOT NULL DEFAULT '{}');
CREATE TABLE service_bays (id UUID PRIMARY KEY, station_id UUID NOT NULL REFERENCES service_stations(id), code VARCHAR(60) UNIQUE NOT NULL, status VARCHAR(30) NOT NULL);
CREATE TABLE jobs (id UUID PRIMARY KEY, job_number VARCHAR(80) UNIQUE NOT NULL, job_type VARCHAR(50) NOT NULL, priority INTEGER NOT NULL, requested_asset_id UUID REFERENCES assets(id), eligible_group VARCHAR(80), source_location_id UUID REFERENCES locations(id), destination_location_id UUID REFERENCES locations(id), required_capabilities JSONB NOT NULL DEFAULT '[]', requested_start_at TIMESTAMPTZ, deadline_at TIMESTAMPTZ, estimated_duration_seconds BIGINT, status VARCHAR(50) NOT NULL, assigned_asset_id UUID REFERENCES assets(id), planned_route_id UUID, actual_start_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, failure_reason TEXT, retry_count INTEGER NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0); CREATE INDEX idx_jobs_status_deadline ON jobs(status,deadline_at); ALTER TABLE assets ADD CONSTRAINT fk_assets_job FOREIGN KEY(current_job_id) REFERENCES jobs(id);
CREATE TABLE job_events (id UUID PRIMARY KEY, job_id UUID NOT NULL REFERENCES jobs(id), from_status VARCHAR(50), to_status VARCHAR(50) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, actor VARCHAR(100) NOT NULL, reason TEXT, metadata JSONB NOT NULL DEFAULT '{}'); CREATE INDEX idx_job_events_job_time ON job_events(job_id,occurred_at);
CREATE TABLE routes (id UUID PRIMARY KEY, job_id UUID REFERENCES jobs(id), graph_version BIGINT NOT NULL, total_distance_m DOUBLE PRECISION NOT NULL, estimated_seconds DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE route_segments (route_id UUID REFERENCES routes(id) ON DELETE CASCADE, sequence_no INTEGER NOT NULL, road_segment_id UUID NOT NULL REFERENCES road_segments(id), PRIMARY KEY(route_id,sequence_no)); ALTER TABLE jobs ADD CONSTRAINT fk_jobs_route FOREIGN KEY(planned_route_id) REFERENCES routes(id);
CREATE TABLE job_assignments (id UUID PRIMARY KEY, job_id UUID NOT NULL REFERENCES jobs(id), asset_id UUID NOT NULL REFERENCES assets(id), score DOUBLE PRECISION, assigned_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_active_asset_assignment ON job_assignments(asset_id) WHERE ended_at IS NULL;
CREATE TABLE dispatch_attempts (id UUID PRIMARY KEY, job_id UUID NOT NULL REFERENCES jobs(id), command_id UUID UNIQUE NOT NULL, attempt_no INTEGER NOT NULL, correlation_id VARCHAR(100) NOT NULL, sent_at TIMESTAMPTZ NOT NULL, acknowledged_at TIMESTAMPTZ, status VARCHAR(30) NOT NULL, UNIQUE(job_id,attempt_no));
CREATE TABLE resource_reservations (id UUID PRIMARY KEY, resource_type VARCHAR(30) NOT NULL, resource_id UUID NOT NULL, job_id UUID NOT NULL REFERENCES jobs(id), expires_at TIMESTAMPTZ NOT NULL, released_at TIMESTAMPTZ); CREATE UNIQUE INDEX uq_active_reservation ON resource_reservations(resource_type,resource_id) WHERE released_at IS NULL;
CREATE TABLE alerts (id UUID PRIMARY KEY, asset_id UUID REFERENCES assets(id), job_id UUID REFERENCES jobs(id), severity VARCHAR(20) NOT NULL, code VARCHAR(60) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, acknowledged_at TIMESTAMPTZ);
CREATE TABLE integration_messages (id UUID PRIMARY KEY, external_message_id VARCHAR(160) NOT NULL, channel VARCHAR(30) NOT NULL, schema_version VARCHAR(20) NOT NULL, correlation_id VARCHAR(100), status VARCHAR(30) NOT NULL, received_at TIMESTAMPTZ NOT NULL, processed_at TIMESTAMPTZ, payload_hash VARCHAR(64) NOT NULL, error TEXT, UNIQUE(channel,external_message_id)); CREATE INDEX idx_integration_received ON integration_messages(received_at);
CREATE TABLE roles (id UUID PRIMARY KEY, name VARCHAR(60) UNIQUE NOT NULL); CREATE TABLE users (id UUID PRIMARY KEY, subject VARCHAR(160) UNIQUE NOT NULL, display_name VARCHAR(160), enabled BOOLEAN NOT NULL DEFAULT TRUE); CREATE TABLE user_roles(user_id UUID REFERENCES users(id),role_id UUID REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE audit_logs (id UUID PRIMARY KEY, occurred_at TIMESTAMPTZ NOT NULL, actor VARCHAR(160) NOT NULL, action VARCHAR(100) NOT NULL, resource_type VARCHAR(60), resource_id VARCHAR(100), correlation_id VARCHAR(100), source_ip VARCHAR(64), before_value JSONB, after_value JSONB); CREATE INDEX idx_audit_time_actor ON audit_logs(occurred_at,actor);
CREATE TABLE scheduler_configuration (config_key VARCHAR(100) PRIMARY KEY, config_value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL, updated_by VARCHAR(160) NOT NULL);
